"""Build an offline interactive presentation page for OptiVest (not Streamlit)."""
import json
from pathlib import Path
from plotly.offline import get_plotlyjs
from engine.finance_examples import EXAMPLES

CSS=r'''
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Outfit:wght@500;600;700;800&display=swap');
*{box-sizing:border-box}body{margin:0;color:#243B52;background:radial-gradient(ellipse at 95% 0,#E6E7FC,transparent 35%),#FAFBFD;font:14px 'DM Sans',Arial,sans-serif}h1,h2,h3{font-family:Outfit,Arial,sans-serif;letter-spacing:-.032em}
.shell{display:grid;grid-template-columns:244px 1fr;min-height:100vh}.nav{background:linear-gradient(170deg,#102A44,#16425A);color:#CFDDE7;padding:26px 15px;position:sticky;height:100vh;top:0}.brand{font:800 26px Outfit;color:white;margin-bottom:3px}.brand span{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;background:#B2E9DF;border-radius:11px;color:#17475A;margin-right:9px}.tagline{color:#8ED7CB;font-size:9px;letter-spacing:.2em;font-weight:800;margin:0 0 32px 46px}.navsection{color:#90AEC1;font-size:10px;font-weight:800;letter-spacing:.12em;margin:27px 8px 11px}.navitem{padding:12px 14px;border-radius:12px;margin:4px 0;font-weight:700;color:#BBD0DD}.navitem.active{background:#21556D;color:white;box-shadow:inset 3px 0 0 #9FE4D7}.sidebar-bottom{position:absolute;bottom:25px;left:15px;right:15px;background:#FFFFFF0B;border:1px solid #FFFFFF23;border-radius:14px;padding:13px;font-size:11px;line-height:1.6}.sidebar-bottom b{color:white}
main{padding:28px clamp(18px,3.3vw,54px) 40px;min-width:0}.top{display:flex;align-items:center;justify-content:space-between;color:#8493A7;font-weight:700;font-size:12px;margin-bottom:18px}.online{color:#3B9B87;background:#E5F6F0;border:1px solid #D4EBE3;padding:8px 12px;border-radius:50px}
.hero{position:relative;isolation:isolate;overflow:hidden;display:flex;align-items:center;min-height:302px;background:linear-gradient(118deg,#14334E,#195067 65%,#2D8E88);border-radius:27px;padding:44px 48px;color:white;box-shadow:0 15px 42px #102F4533}.herocopy{z-index:2;max-width:66%}.eyebrow{letter-spacing:.18em;color:#A4E9DC;font-size:10px;font-weight:800;margin-bottom:16px}.hero h1{font-size:clamp(33px,3.4vw,50px);line-height:1.15;margin:0 0 14px;color:white}.hero p{font-size:14px;max-width:650px;color:#D2E5E9;line-height:1.75;margin:0}.pills{display:flex;gap:8px;flex-wrap:wrap;margin-top:23px}.pills span{border-radius:30px;background:#ffffff17;border:1px solid #ffffff40;padding:7px 12px;font-size:10px;font-weight:700}.art{position:absolute;right:5%;top:6%;height:90%;width:30%}.sphere{position:absolute;top:15%;right:13%;height:170px;width:170px;border-radius:50%;background:radial-gradient(circle at 25% 20%,#D6F7EB,#86CED1 32%,#9996DE 69%,#306D84);box-shadow:inset -20px -25px 38px #10455B60,0 20px 45px #092A4650;animation:float 5s ease-in-out infinite}.orbit{position:absolute;right:0;top:1%;height:260px;width:260px;border:1px solid #E4F8F850;border-radius:50%;transform:rotate(-24deg);animation:rotate 20s linear infinite}.orbit.two{width:316px;height:200px;top:17%;right:-8%;animation-direction:reverse}.spark{position:absolute;height:14px;width:14px;background:#FFCEAB;border-radius:50%;top:10%;right:11%;box-shadow:0 0 23px #FFD8BC;animation:float 3s ease-in-out infinite}.glass{position:absolute;top:8%;left:-10%;background:#FFFFFF22;border:1px solid #FFFFFF60;border-radius:15px;padding:12px 17px;backdrop-filter:blur(9px);color:white;animation:float 7s ease-in-out infinite;box-shadow:0 8px 22px #142D3F30}.glass strong{font-size:24px;color:#CAF6E9}.glass small{display:block;font-size:10px;color:#E3F6F8}.mini-bars{position:absolute;bottom:0;right:0;display:flex;align-items:end;gap:6px;padding:12px;border-radius:13px;background:#FFFFFF25;backdrop-filter:blur(8px);height:65px}.mini-bars i{width:13px;background:#ACEDDB;border-radius:5px 5px 0 0;animation:bar 2s ease-in-out infinite alternate}.mini-bars i:nth-child(1){height:35%}.mini-bars i:nth-child(2){height:80%}.mini-bars i:nth-child(3){height:56%}.mini-bars i:nth-child(4){height:99%}.mini-bars i:nth-child(5){height:70%}
@keyframes rotate{to{transform:rotate(336deg)}}@keyframes float{50%{transform:translateY(-12px)}}@keyframes bar{to{transform-origin:bottom;transform:scaleY(.65)}}
.controlrow{display:flex;justify-content:space-between;align-items:end;flex-wrap:wrap;gap:12px;margin:22px 0}.controlrow h2{font-size:22px;margin:0}.controlrow small{color:#8390A3}.fields{display:flex;gap:12px;align-items:end}label{color:#667891;font-weight:700;font-size:11px;display:block;margin-bottom:6px}select{padding:10px 14px;border-radius:12px;border:1px solid #DFE7F0;color:#30445F;font:600 12px 'DM Sans';background:white;min-width:205px}.pillright{color:#4C8D85;border:1px solid #CEE9DF;background:#EFFBF6;border-radius:30px;font-size:11px;font-weight:800;padding:8px 11px}
.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:16px 0 19px}.metric{background:white;border:1px solid #E8ECF4;border-radius:19px;padding:20px 21px;box-shadow:0 7px 22px #3F52750A;position:relative;overflow:hidden;transition:transform .23s ease}.metric:hover{transform:translateY(-3px)}.metric:before{content:'';position:absolute;left:0;top:16px;bottom:16px;width:4px;border-radius:3px;background:var(--accent,#65C4AF)}.metric span{color:#8794A7;display:block;font-size:11px;font-weight:800;letter-spacing:.07em;text-transform:uppercase}.metric b{font:800 clamp(20px,2vw,29px) Outfit;color:#263E58;display:block;margin:7px 0 3px}.metric small{font-size:11px;color:#7C9F96;font-weight:600}
.grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,1fr);gap:17px}.panel{background:white;border:1px solid #E7EBF3;border-radius:20px;padding:19px;box-shadow:0 7px 20px #455F7809;min-width:0}.panel h2{font-size:19px;margin:0 0 5px}.panel small{color:#8A98A8}.plot{height:330px}.wide{grid-column:1/-1}.cardrow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.step{background:#F8FAFE;border:1px solid #E6ECF5;border-top:3px solid #8DD7C3;border-radius:15px;padding:14px 17px}.step h3{font-size:15px;margin:4px 0}.step p{color:#8492A7;font-size:12px;line-height:1.5;margin:0}.sectiontitle{font-size:13px;color:#52677C;font-weight:800;margin:10px 0}.sliderrow{display:grid;grid-template-columns:1fr 1fr;gap:15px}.inputblock{padding:10px 0}.inputblock strong{float:right;color:#2C8E87;font-size:12px}input[type=range]{accent-color:#38A59F;width:100%;cursor:pointer}.note{border-radius:12px;background:#EFFAF5;color:#4B8275;border-left:4px solid #76C9B3;padding:13px 16px;font-size:12px;margin-top:17px;line-height:1.6}.footer{color:#8493A2;text-align:center;margin-top:32px;font-size:11px}
@media(max-width:1100px){.shell{grid-template-columns:190px 1fr}.metrics{grid-template-columns:repeat(2,1fr)}.art{opacity:.55}.herocopy{max-width:80%}}
@media(max-width:790px){.shell{display:block}.nav{position:static;height:auto;padding:12px}.navsection,.navitem,.sidebar-bottom{display:none}.brand{margin:0}.tagline{margin:0 0 0 44px}main{padding:17px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.hero{padding:34px 25px;min-height:0}.herocopy{max-width:100%}.art{display:none}.cardrow{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
'''
HTML=r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OptiVest · Aperçu interactif</title><style>__CSS__</style><script>__PLOTLY__</script></head><body><div class="shell">
<aside class="nav"><div class="brand"><span>◈</span>OptiVest</div><p class="tagline">INVESTMENT INTELLIGENCE</p>
<div class="navsection">ESPACE DE TRAVAIL</div><div class="navitem active">◈ &nbsp; Vue d'ensemble</div><div class="navitem">▤ &nbsp; Étude & projets</div><div class="navitem">↗ &nbsp; Analyse financière</div>
<div class="navsection">DÉCISION MULTICRITÈRE</div><div class="navitem">⚖ &nbsp; Pondération des critères</div><div class="navitem">▥ &nbsp; Classement MCDM</div><div class="navitem">⇄ &nbsp; Comparaison des rangs</div>
<div class="navsection">RISQUE & ARBITRAGE</div><div class="navitem">◌ &nbsp; Scénarios financiers</div><div class="navitem">◇ &nbsp; Allocation du budget</div>
<div class="navsection">RESTITUTION</div><div class="navitem">▤ &nbsp; Rapport d'investissement</div>
<div class="sidebar-bottom"><b>APERCU AUTONOME</b><br>Les calculs avancés et la navigation complète se trouvent dans l'application Streamlit du projet.</div></aside>
<main><div class="top"><span>INVESTMENT STUDIO / DASHBOARD</span><span class="online">● Démonstration interactive</span></div>
<div class="hero"><div class="herocopy"><div class="eyebrow">● INVESTMENT DECISION INTELLIGENCE</div><h1>Décider mieux.<br>Investir plus intelligemment.</h1><p>Du cash-flow à la recommandation : analyse tes projets d’investissement, compare les opportunités et mesure les scénarios qui influencent la valeur.</p><div class="pills"><span>◆ Analyse financière</span><span>◆ Décision multicritère</span><span>◆ Risque & scénarios</span></div></div><div class="art"><div class="orbit"></div><div class="orbit two"></div><div class="sphere"></div><div class="spark"></div><div class="glass">↗ &nbsp;<strong>OptiVest</strong><small>Financial intelligence</small></div><div class="mini-bars"><i></i><i></i><i></i><i></i><i></i></div></div></div>
<div class="controlrow"><div><h2>Vue d’ensemble des investissements</h2><small>Projets fictifs · taux et budget ajustables</small></div><div class="fields"><div><label>Étude active</label><select id="dataset"></select></div><span class="pillright">● Valeurs recalculées</span></div></div>
<div class="metrics"><div class="metric" style="--accent:#6BC8B7"><span>Budget disponible</span><b id="budgetKpi">—</b><small>Millions de dirhams</small></div><div class="metric" style="--accent:#A2A1E5"><span>Projets évalués</span><b id="nProjects">—</b><small>Opportunités analysées</small></div><div class="metric" style="--accent:#F1B29B"><span>VAN totale</span><b id="npvKpi">—</b><small>Somme descriptive</small></div><div class="metric" style="--accent:#E4BE6F"><span>Meilleure VAN</span><b id="leader">—</b><small>Projet le plus créateur de valeur</small></div></div>
<div class="grid"><div class="panel"><h2>Valeur actuelle nette</h2><small>VAN par projet · millions MAD</small><div id="npvplot" class="plot"></div></div>
<div class="panel"><h2>Structure des critères MCDM</h2><small>Poids initiaux, modifiables dans Streamlit</small><div id="donutplot" class="plot"></div></div>
<div class="panel"><h2>Évolution des flux financiers</h2><small>Cash-flows prévisionnels sur cinq ans</small><div id="flowplot" class="plot"></div></div>
<div class="panel"><h2>Explorer les hypothèses</h2><small>Modifie les paramètres et observe les changements</small><div class="sliderrow"><div class="inputblock"><label>Taux d'actualisation <strong id="rateVal">10 %</strong></label><input type="range" id="rate" min="0" max="25" step=".5" value="10"></div><div class="inputblock"><label>Budget (M MAD) <strong id="budgetVal">30</strong></label><input type="range" id="budget" min="5" max="70" step="1" value="30"></div></div><div id="allocateplot" class="plot" style="height:205px"></div><div class="note" id="allocation">L'allocation présentée maximise la somme des VAN, sous budget limité et projets supposés indépendants.</div></div>
<div class="panel wide"><h2>Un parcours clair, de la donnée à la décision</h2><div class="cardrow"><div class="step"><small>ÉTAPE 01</small><h3>Construire l'étude</h3><p>Investissements, risques, cash-flows et hypothèses financières.</p></div><div class="step"><small>ÉTAPE 02</small><h3>Évaluer et comparer</h3><p>VAN, TRI, AHP, BWM, TOPSIS, VIKOR, surclassement.</p></div><div class="step"><small>ÉTAPE 03</small><h3>Arbitrer le budget</h3><p>Scénarios, robustesse, combinaison des projets et rapport.</p></div></div></div></div>
<div class="footer">OptiVest — aperçu de présentation indépendant de Streamlit · aucune donnée réelle · ouvrir l'application Python pour les modules complets.</div></main></div>
<script>
const studies=__EXAMPLES__,COLORS=['#4DB7AC','#9B9CE5','#F2AF91','#E7C375','#A4C7EB'];let study=JSON.parse(JSON.stringify(Object.values(studies)[0]));const $=x=>document.getElementById(x);
const fmt=v=>Number(v).toFixed(2),money=v=>(v>=0?'+':'')+fmt(v)+' M';
function npv(p,r){return p.cashflows.reduce((s,c,t)=>s+c/Math.pow(1+r,t+1),-p.investment)}
function allocation(items,rate,budget){let best={value:0,cost:0,names:[]},n=items.length;for(let bits=0;bits<(1<<n);bits++){let value=0,cost=0,names=[];for(let j=0;j<n;j++)if(bits&(1<<j)){value+=npv(items[j],rate);cost+=items[j].investment;names.push(items[j].name)}if(cost<=budget+1e-9&&value>best.value){best={value,cost,names}}}return best}
function plotLayout(height,overrides={}){return {height,paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{family:'DM Sans',color:'#70849B',size:11},margin:{t:10,r:20,l:70,b:52},...overrides}}
const conf={displayModeBar:false,displaylogo:false,responsive:true};
function draw(){let r=Number($('rate').value)/100,b=Number($('budget').value),list=study.projects,values=list.map(x=>npv(x,r)),bestId=values.indexOf(Math.max(...values)),al=allocation(list,r,b);$('budgetKpi').textContent=b.toFixed(1)+' M';$('nProjects').textContent=list.length;$('npvKpi').textContent=money(values.reduce((a,b)=>a+b,0));$('leader').textContent=list[bestId].name;$('rateVal').textContent=(r*100).toFixed(1)+' %';$('budgetVal').textContent=b.toFixed(0)+' M';
Plotly.react('npvplot',[{type:'bar',orientation:'h',x:values,y:list.map(p=>p.name),marker:{color:values.map(v=>v>=0?'#55BCAB':'#F2AC91')},text:values.map(v=>money(v)),textposition:'outside',cliponaxis:false}],plotLayout(330,{margin:{t:18,r:50,l:125,b:40},yaxis:{autorange:'reversed'}}),conf);
Plotly.react('donutplot',[{type:'pie',hole:.7,labels:['VAN','Indice de profitabilité','Risque','Payback','Alignement'],values:[34,16,23,14,13],textinfo:'percent',marker:{colors:COLORS},sort:false}],plotLayout(330,{margin:{t:5,r:6,l:6,b:35},legend:{orientation:'h',y:-.1},annotations:[{text:'100 %<br><span style="font-size:11px">des poids</span>',x:.5,y:.5,showarrow:false,font:{size:19,color:'#30445D'}}]}),conf);
Plotly.react('flowplot',list.map((p,i)=>({type:'scatter',mode:'lines+markers',x:[1,2,3,4,5],y:p.cashflows,line:{color:COLORS[i],width:3,shape:'spline'},marker:{size:6},name:p.name})),plotLayout(330,{margin:{t:10,r:10,l:44,b:48},legend:{orientation:'h',y:-.22,font:{size:10}},xaxis:{title:'Année'},yaxis:{title:'M MAD'}}),conf);
let used=al.cost,unused=b-used;Plotly.react('allocateplot',[{type:'bar',orientation:'h',x:[used],y:['Budget'],marker:{color:'#4DB7AC'},name:'Capital retenu',text:[fmt(used)+' M'],textposition:'inside'},{type:'bar',orientation:'h',x:[unused],y:['Budget'],marker:{color:'#E2E8F2'},name:'Non utilisé',text:[fmt(unused)+' M'],textposition:'inside'}],plotLayout(205,{barmode:'stack',margin:{t:28,r:14,l:58,b:32},showlegend:true,legend:{orientation:'h',y:-.3}}),conf);
$('allocation').innerHTML='<b>Projets finançables retenus :</b> '+(al.names.join(', ')||'Aucun')+'<br>VAN du portefeuille : '+money(al.value)+' · Capital utilisé : '+fmt(used)+' M';}
for(let name of Object.keys(studies)){let op=document.createElement('option');op.value=name;op.textContent=name;$('dataset').appendChild(op)}
$('dataset').addEventListener('change',e=>{study=JSON.parse(JSON.stringify(studies[e.target.value]));$('rate').value=study.rate*100;$('budget').value=study.budget;draw()});$('rate').addEventListener('input',draw);$('budget').addEventListener('input',draw);$('rate').value=study.rate*100;$('budget').value=study.budget;draw();
</script></body></html>'''

def main():
    path=Path(__file__).parent/'Apercu_OptiVest_Interactif.html'
    html=HTML.replace('__CSS__',CSS).replace('__PLOTLY__',get_plotlyjs()).replace('__EXAMPLES__',json.dumps(EXAMPLES,ensure_ascii=False))
    path.write_text(html,encoding='utf-8')
    print(path,round(path.stat().st_size/1024/1024,2),'MB')

if __name__=='__main__':main()
